window.NEO_DATA_MK2_KEY = {"set_id":2,"g":{"r_ctw_01":{"blanks":{"1":"poison","2":"must","3":"eaten","4":"is","5":"directly","6":"fangs","7":"or","8":"spines","9":"spiders","10":"and"},"kr":{"passage":["독액은 일부 동물이 사냥하거나 자신을 방어하기 위해 만들어 내는 해로운 화학물질 혼합물입니다. 먹어야 효과가 나타나는 독과 달리, 독액은 송곳니나 침, 또는 날카로운 가시를 통해 곧바로 주입됩니다. 뱀, 거미, 전갈, 그리고 일부 물고기가 저마다 다른 방식으로 이를 이용합니다. 동물이 공격하면 독액은 희생물의 신경계나 혈액, 근육을 공격할 수 있습니다. 독액은 매우 빠르게 작용하기 때문에, 먹잇감은 한번 당하면 쉽게 달아나지 못합니다. 과학자들은 이제 이 물질들을 면밀히 연구하는데, 그중 다수가 통증과 심각한 질병을 치료하는 값진 약으로 바뀔 수 있기 때문입니다."],"blanks":{"1":"'Unlike ___, which must be eaten'로 독액과 대비되는 **명사** 자리예요. '먹어야' 효과가 나면서 **poi__**로 시작하는 건 '**독(poison)**'이에요.","2":"'which ___ be eaten'로 be 앞 **조동사** 자리예요. '먹혀야 한다'는 의무를 나타내고 **mu__**로 시작하는 조동사는 '**must**'예요.","3":"'must be ___'로 수동태의 **과거분사** 자리예요. 독은 '먹혀야' 작용하니 **ea__**로 시작하는 '**eaten**'이 와요.","4":"'venom ___ injected'로 수동태를 만드는 **be동사** 자리예요. 주어 venom(단수)에 맞고 **i_**(한 글자 더)인 건 '**is**'예요.","5":"동사 injected를 꾸미는 **부사** 자리예요. '곧바로 주입된다'는 뜻이고 **dire__**로 시작하는 '**directly**'가 와요.","6":"'injected through ___'로 주입 통로가 되는 **명사**예요. **fa__**로 시작하며 뱀의 주입 기관은 '**송곳니(fangs)**'예요.","7":"'fangs, stingers, ___ sharp spines'로 나열을 잇는 **접속사** 자리예요. **o_**로 시작하는 등위접속사는 '**or**'예요.","8":"'sharp ___'로 sharp가 꾸미는 **명사**예요. **spi__**로 시작하며 '날카로운 가시'는 '**spines**'예요.","9":"'Snakes, ___, scorpions'로 나열되는 동물 **명사**예요. **spi__**로 시작하며 독을 쓰는 동물은 '**거미(spiders)**'예요(8번 spines는 가시라 자리가 달라요).","10":"'scorpions, ___ certain fish'로 마지막 나열을 잇는 **접속사** 자리예요. **a__**로 시작하는 'A, B, and C'의 '**and**'가 와요."}}},"r_dl_01":{"q":{"r_dl_01_1":{"a":0,"why":"'실시간 지도만 열면 앱이 자꾸 **crashing**한다'는 건, 앱이 갑자기 **꺼진다**는 뜻이에요. 그래서 '꺼짐(Shutting down)'이 가장 가까워요. 실제로 무언가와 부딪히는(colliding) 게 아니라 비유적인 IT 표현이에요.","wrong":[null,null,null,null],"kr":{"stem":"맥락상 \"crashing\"과 의미가 가장 가까운 것은?","opt":["꺼짐","느리게 작동함","요란하게 충돌함","광고를 띄움"]}},"r_dl_01_2":{"a":2,"why":"'**도착 시간이 완전히 틀리게 나오는 바람에** 지각할 뻔했다'가 근거예요. 그래서 '잘못된 시간이 표시돼서'가 정답이에요. 버스가 안 온 게 아니라 시간 정보가 틀린 거예요.","wrong":[null,null,null,null],"kr":{"stem":"글쓴이는 왜 수업에 지각할 뻔했나요?","opt":["버스가 오지 않아서","요금 때문에 계정이 잠겨서","잘못된 시간이 표시돼서","화면이 헷갈려서"]}}},"kr":{"passage":["저만 새 BusTracker 업데이트 때문에 고생하나요? 어제부터 실시간 지도만 열면 앱이 자꾸 튕기고, 아침 노선 알림은 아예 안 떴어요. 예전 화면이 훨씬 안정적이고 편했는데. 도착 시간이 완전히 틀리게 나오는 바람에 수업에 지각할 뻔했으니 얼른 고쳐 주세요."]}},"r_dl_02":{"q":{"r_dl_02_1":{"a":1,"why":"칭찬이 많지만 '**진도 느린 첫 2주가 지루했다**'는 뚜렷한 단점도 짚어요. 극찬 일변도가 아니라 장단점을 함께 말하니, 태도는 '**어느 정도 만족(Somewhat satisfied)**'이에요. '몹시 실망'이나 '무관심'은 정반대예요.","wrong":[null,null,null,null],"kr":{"stem":"이 강좌에 대한 글쓴이의 태도는 어떤가요?","opt":["몹시 실망함","어느 정도 만족함","완전히 무관심함","점점 더 열광함"]}},"r_dl_02_2":{"a":0,"why":"'질문을 보내면 **늘 하루 안에 답해 주셨다**'가 근거예요. 그래서 '빠른 답을 받았다(prompt replies)'가 추론돼요. 개인 과외(private tutoring)라는 말은 없어요.","wrong":[null,null,null,null],"kr":{"stem":"강좌 중 질문이 있었던 학생에 대해 무엇을 추론할 수 있나요?","opt":["빠른 답을 받았다.","개인 과외를 받았다.","영상으로 배웠다.","수업 중에만 질문할 수 있었다."]}},"r_dl_02_3":{"a":2,"why":"글쓴이가 콕 집은 단점은 '**진도가 느린 첫 2주**가 (스프레드시트를 아는 사람에겐) 겹치는 느낌'이었어요. 그래서 '초반 수업이 기초를 반복했다'가 정답이에요. 데이터셋은 무료였고 수료증은 바로 떴으니 나머지는 틀려요.","wrong":[null,null,null,null],"kr":{"stem":"글쓴이가 지적한 주된 단점은 무엇인가요?","opt":["수료증이 늦게 왔다.","데이터셋에 추가 비용이 들었다.","초반 수업이 기초를 반복했다.","일부 수업이 너무 길었다."]}}},"kr":{"passage":["해나 조","브라이트패스에서 6주짜리 '데이터 시각화 입문' 강좌를 막 끝내고, 수강을 고민하는 분들을 위해 솔직한 생각 몇 가지를 나눠 볼게요. 각 수업은 대략 90분이었고, 학생을 진심으로 아끼는 오카포 박사님은 질문을 보내면 늘 하루 안에 답해 주셨어요. 수업이 정말 직접 해 보는 방식이라, 영상만 보는 게 아니라 매주 실제로 작동하는 인터랙티브 차트를 만들었어요.","가장 좋았던 점은 연습용 데이터셋이 추가 비용 없이 포함돼 있었다는 거예요. 요즘 은근히 드문 일이죠. 유일한 단점은, 진도가 느린 첫 2주가 스프레드시트를 이미 아는 사람에겐 좀 지루하게 느껴졌다는 거예요. 그래도 지금껏 들은 온라인 강좌 중 가장 알찼고, 최종 과제를 제출하자마자 수료증이 떴어요. 실무에 바로 쓸 기술을 원한다면 충분히 값어치를 해요."]}},"r_dl_03":{"q":{"r_dl_03_1":{"a":0,"why":"","wrong":[null,null,null,null]},"r_dl_03_2":{"a":2,"why":"","wrong":[null,null,null,null]},"r_dl_03_3":{"a":3,"why":"","wrong":[null,null,null,null]}}},"r_ac_01":{"q":{"r_ac_01_1":{"a":1,"why":"'이 초기 공연은 귀족 계층의 **우아함과 절제**를 보여 주기 위한 것이었다'가 근거예요. 그래서 '귀족의 우아함과 절제를 드러내려고'가 정답이에요. 많은 이를 즐겁게 하려던 오락(amuse)이 아니에요.","wrong":[null,null,null,null],"kr":{"stem":"지문에 따르면, 가장 초기의 궁정 발레는 무엇을 위한 것이었나요?","opt":["궁정의 많은 이를 즐겁게 하려고","귀족의 우아함과 절제를 드러내려고","귀족을 전문 무용수로 키우려고","귀족의 절제와 우아함을 막으려고"]}},"r_ac_01_2":{"a":2,"why":"'무용 교사들은 ... 정확히 가르치고 반복할 수 있도록 **움직임에 이름을 붙였다**'가 근거예요. 그래서 '동작에 이름을 붙여 전달할 수 있게 했다'가 정답이에요. 작곡(A)이나 극장 건립(B)은 무용 교사가 한 일이 아니에요.","wrong":[null,null,null,null],"kr":{"stem":"지문은 무용 교사들이 어떻게 발레를 다듬었다고 말하나요?","opt":["각 춤에 맞춰 음악을 작곡함으로써","관객이 볼 수 있는 최초의 극장을 세움으로써","동작에 이름을 붙여 남에게 전할 수 있게 함으로써","더 긴 춤을 지어내며 이야기를 전함으로써"]}},"r_ac_01_3":{"a":3,"why":"'기술적 요구가 높아지자 아마추어 궁정인이 **숙련된 전문가로 대체되었다**'가 근거예요. 그래서 '귀족 대신 전문가에게 의존하게 됐다'가 추론돼요. 더 쉬워졌다는 B는 정반대예요.","wrong":[null,null,null,null],"kr":{"stem":"기술적 요구가 높아지면서 발레에 대해 무엇을 추론할 수 있나요?","opt":["새로운 종류의 시설이 생겨났다.","더 쉬워져 더 많은 귀족이 출 수 있었다.","다시 궁정 안에서만 공연되었다.","귀족 대신 전문가에게 의존하게 되었다."]}},"r_ac_01_4":{"a":0,"why":"'19세기에 이르러 **발레**는 고유의(its own) 용어를 갖춘 분야가 되었다'는 문장이에요. its는 바로 그 주어 '**발레(ballet)**'를 가리켜요.","wrong":[null,null,null,null],"kr":{"stem":"\"its own vocabulary\"에서 \"its\"가 가리키는 것은?","opt":["발레","19세기","훈련법","이름난 무용수들"]}},"r_ac_01_5":{"a":1,"why":"본문은 발레가 궁정 과시로 시작(A)해, 무용 교사에게 배우고(C), 1800년대엔 세련된 예술이 됐다(D)고 해요. 하지만 '**수 세기 동안 궁전 안 아마추어 공연으로 남았다**'는 건, 전문가·극장으로 옮겨 갔다는 흐름과 정반대예요. 그래서 B가 본문과 어긋나 정답(EXCEPT)이에요.","wrong":[null,null,null,null],"kr":{"stem":"지문에 따르면, 발레의 발전을 설명하는 것으로 옳지 않은 것은?","opt":["르네상스 유럽 궁정에서 궁정 과시로 시작되었다.","수 세기 동안 궁전 안 아마추어 공연으로 남았다.","일부 사람은 무용 교사에게 발레를 배웠다.","1800년대에 세련된 공연 형식이 되었다."]}}},"kr":{"passage":["발레는 대중 오락이 아니라 르네상스 유럽 궁정 안의 과시 형식으로 시작되었습니다. 화려한 궁정 축제에서 귀족들은 음악과 시, 볼거리를 결합한 정교하게 짜인 춤을 추었습니다. 이 초기 공연은 귀족 계층의 우아함과 절제를 보여 주기 위한 것이었고, 참가자들은 훈련된 전문가라기보다 궁정의 구성원인 경우가 많았습니다.","시간이 지나면서 이 예술은 더 체계적이고 까다로워졌습니다. 무용 교사들은 자세와 동작을 체계화하기 시작해, 정확히 가르치고 반복할 수 있도록 움직임에 이름을 붙였습니다. 기술적 요구가 높아지자, 무대에서 아마추어 궁정인은 점차 숙련된 전문가로 대체되었습니다. 공연은 궁전 홀에서 극장으로 옮겨 갔고, 그곳에서 돈을 낸 관객이 관람할 수 있었습니다.","안무가들은 춤을 위해 특별히 작곡된 음악에 맞추어 움직임으로 이야기를 전하는 더 긴 작품을 만들었습니다. 19세기에 이르러 발레는 고유의 용어와 훈련법, 이름난 무용수를 갖춘 고도로 세련된 분야가 되었습니다. 무용수들은 균형과 턴아웃, 무게가 없는 듯한 착각을 익히는 데 여러 해를 쏟았습니다. 한때 귀족의 궁정 오락이던 것이, 신체적 난도와 표현력 모두로 여러 나라에서 찬사받는 진지한 공연 예술로 탈바꿈했습니다."]}},"r_ctw_02":{"blanks":{"1":"carry","2":"pieces","3":"stone","4":"carving","5":"and","6":"over","7":"periods","8":"time","9":"the","10":"waves"},"kr":{"passage":["침식은 물과 바람, 얼음이 암석과 흙을 서서히 깎아 내는 과정입니다. 강은 작은 돌 조각을 하류로 실어 나르며, 오랜 세월에 걸쳐 계곡과 협곡을 깎아 냅니다. 해안을 따라서는 파도가 절벽에 부딪혀 이를 조금씩 모래로 부숩니다. 바람은 헐거운 입자를 들어 올려 멀리 떨어뜨리며 모래언덕을 빚고 단단한 표면을 매끄럽게 만듭니다. 추운 지역에서는 움직이는 얼음이 땅을 긁고 무거운 바위를 먼 거리까지 끌고 갑니다. 각각의 변화는 작지만 그 효과는 수천 년에 걸쳐 쌓입니다. 이렇게 침식은 행성 전체의 표면을 끊임없이 다시 빚어냅니다."],"blanks":{"1":"주어 Rivers 뒤 **동사** 자리예요. **ca__**로 시작하며 조각을 하류로 '실어 나른다'는 '**carry**'예요.","2":"'tiny ___ of stone'로 tiny가 꾸미는 **명사**예요. **pie__**로 시작하며 '작은 조각'은 '**pieces**'예요.","3":"'pieces of ___'로 of 뒤 **명사**예요. **st__**로 시작하며 강이 나르는 것은 '**돌(stone)**'이에요.","4":"'실어 나르며 ~한다'는 동시 동작의 **분사(-ing)** 자리예요. **car__**로 시작하며 계곡을 '깎아 낸다'는 '**carving**'이에요.","5":"'valleys ___ canyons'로 두 명사를 잇는 **접속사**예요. **a__**로 시작하는 '**and**'가 와요.","6":"'___ long periods of time'로 기간을 나타내는 **전치사**예요. **ov__**로 시작하며 '~에 걸쳐'를 뜻하는 '**over**'가 와요.","7":"'long ___ of time'로 long이 꾸미는 **명사**예요. **per__**로 시작하며 '오랜 기간'은 '**periods**'예요.","8":"'periods of ___'로 of 뒤 **명사**예요. **ti__**로 시작하며 'periods of time(오랜 세월)'의 '**time**'이에요.","9":"'Along ___ coast'로 특정 해안을 가리키는 **관사**예요. **t__**로 시작하는 정관사 '**the**'예요.","10":"'___ pound against cliffs'로 절벽에 부딪히는 주어 **명사**예요. **wa__**로 시작하며 해안에서 절벽을 치는 것은 '**파도(waves)**'예요."}}},"r_dl_04":{"q":{"r_dl_04_1":{"a":3,"why":"니나가 자리 밑에 뒀는데 오마르가 '**강의실이 지금 비어 있다**'고 했어요. 즉 물병이 **원래 둔 자리에서 사라졌다**고 추론돼요. 뒤에 안내 데스크에서 발견되지만, 자리엔 없었어요.","wrong":[null,null,null,null],"kr":{"stem":"물병에 대해 무엇을 추론할 수 있나요?","opt":["니나가 화학 실험실에 두고 왔다.","오마르가 대신 보관하고 있다.","오마르가 맡겨 두었다.","니나가 둔 자리에서 사라졌다."]}},"r_dl_04_2":{"a":1,"why":"'**5시 전에 와서 찾아가라(come by ... to pick it up)**'가 근거예요. 그래서 '가서 찾아오라(Collect it)'가 정답이에요. '5시에'가 아니라 '5시 전에'라 A는 틀려요.","wrong":[null,null,null,null],"kr":{"stem":"오마르는 니나에게 무엇을 하라고 하나요?","opt":["5시에 찾아라.","가서 찾아와라.","자리 밑을 뒤져 봐라.","새로 사라."]}}},"kr":{"passage":["니나: 화학 강의 끝나고 제 회색 물병 가져가신 분 있어요? 214호 제 자리 밑에 두고 왔어요.","오마르: 못 봤는데, 방금 지나가 보니 강의실이 지금 비어 있어요.","니나: 아 참. 안내 데스크 좀 확인해 줄래요? 분실물은 보통 거기에 둬요.","오마르: 좋은 생각이에요. 직원분이 회색 물병이 들어왔대요. 5시 전에 와서 찾아가세요.","니나: 완전 은인이에요. 지금 갈게요."]}},"r_dl_05":{"q":{"r_dl_05_1":{"a":0,"why":"광고 전체가 '이력서 검토·재작성 **서비스**'를 소개하고 가격과 포함 사항을 안내해요. 그래서 '작문 서비스를 홍보하는 것'이 목적이에요. 면접 기술을 가르치거나 소프트웨어를 파는 게 아니에요.","wrong":[null,null,null,null],"kr":{"stem":"이 광고의 주된 목적은 무엇인가요?","opt":["작문 서비스를 홍보하려고","졸업생 취업을 도우려고","면접 기술을 가르치려고","구직 소프트웨어를 팔려고"]}},"r_dl_05_2":{"a":3,"why":"'밋밋한 나열을 성과 중심의 **sharp**한 문서로 바꾼다'는 맥락이에요. 여기서 sharp는 경사(steep)나 신맛이 아니라 '군더더기 없고 효과적인'이라는 뜻이라 '효과적인(effective)'이 가장 가까워요.","wrong":[null,null,null,null],"kr":{"stem":"지문에서 쓰인 대로 \"sharp\"와 의미가 가장 가까운 것은?","opt":["가파른","갑작스러운","신맛의","효과적인"]}},"r_dl_05_3":{"a":2,"why":"'**두 차례 수정이 추가 비용 없이 포함된다**'가 근거예요. 그래서 '두 번의 수정(Two edits)'이 정답이에요. 자기소개서는 20달러 추가라 무료가 아니에요.","wrong":[null,null,null,null],"kr":{"stem":"추가 비용 없이 포함되는 것은 무엇인가요?","opt":["자기소개서","상담","두 번의 수정","당일 배송"]}}},"kr":{"passage":["면접까지 가자: 이력서 작성 서비스","이력서가 인상을 남길 시간은 약 6초뿐이에요. 그래서 저희 서비스는 학생과 사회 초년생이 밋밋한 경력 나열을 성과 중심의 날카로운 문서로 바꾸도록 도와요. 지원하는 직무에 맞춰 이력서를 손보고, 고용주가 가장 눈여겨보는 성과를 부각해요.","패키지","기본 패키지: 이력서 전체 검토와 재작성 45달러.","어울리는 자기소개서 추가 시 20달러 추가.","포함 사항","두 차례 수정이 추가 비용 없이 포함돼요.","대부분의 초안은 영업일 기준 3일 안에 돌려드려요.","시작하려면 현재 이력서를 hello@careerlift.co로 보내 주세요."]}},"r_ctw_03":{"blanks":{"1":"insulating","2":"usually","3":"two","4":"layers","5":"cooperate","6":"against","7":"cold","8":"undercoat","9":"warm","10":"near"},"kr":{"passage":["얼어붙은 북쪽에서 살아남는 동물은 단순히 몸을 덮는 것 이상을 하는 털에 의존합니다. 이들의 단열 털은 대개 두 겹의 층으로 이루어지는데, 두 층이 추위를 막기 위해 촘촘히 협력합니다. 빽빽한 속털은 피부 가까이에 따뜻한 공기를 가두어, 매서운 바람에도 견디는 꾸준한 단열을 제공합니다. 물을 잘 털어 내는 긴 겉털은 사나운 폭풍 속에서도 동물을 마른 상태로 유지합니다. 많은 종에서 털은 겨울 동안 하얗게 변해, 끝없는 눈밭에서 완벽한 위장이 되어 줍니다. 어떤 털은 심지어 속이 비어 있어, 공기를 추가로 가두어 온기와 편안함을 높입니다."],"blanks":{"1":"'Their ___ coats'로 coats를 꾸미는 **형용사** 자리예요. **insul__**로 시작하며 '단열하는'을 뜻하는 '**insulating**'이 와요.","2":"동사 contain을 꾸미는 **부사** 자리예요. **usu__**로 시작하며 '대개'를 뜻하는 '**usually**'가 와요.","3":"'___ separate layers'로 layers를 세는 **수사**예요. 뒤에 속털·겉털 두 종류가 나오니 **t__**로 시작하는 '**two**'가 와요.","4":"'two separate ___'로 two가 세는 **명사**예요. **lay__**로 시작하며 털의 '층'은 '**layers**'예요.","5":"관계대명사 that 뒤 **동사** 자리예요. 두 층이 '협력한다'는 뜻이고 **coop__**로 시작하는 '**cooperate**'가 와요.","6":"'cooperate tightly ___ the cold'로 '추위에 맞서'를 뜻하는 **전치사**예요. **aga__**로 시작하는 '**against**'가 와요.","7":"'against the ___'로 the 뒤 **명사**예요. **co__**로 시작하며 막아야 할 대상은 '**추위(cold)**'예요.","8":"'A dense ___'로 dense가 꾸미는 **명사**예요. **unde__**로 시작하며 피부 가까운 '속털'은 '**undercoat**'예요.","9":"'traps ___ air'로 air를 꾸미는 **형용사**예요. **wa__**로 시작하며 속털이 가두는 건 '**따뜻한(warm)**' 공기예요.","10":"'air ___ the skin'로 위치를 나타내는 **전치사**예요. **ne__**로 시작하며 '~ 가까이'를 뜻하는 '**near**'가 와요."}}},"r_ac_02":{"q":{"r_ac_02_1":{"a":1,"why":"'익숙한 생명체와 **똑같은** 기본 대사·번식을 유지하지만, 보통 단백질이라면 파괴될 환경에서 그렇게 한다'가 근거예요. 그래서 '치명적인 환경 속에서 평범한 생명 활동을 해낸다'가 정답이에요. 남다른 대사(A)가 아니라 '똑같은' 대사라 A는 틀려요.","wrong":[null,null,null,null],"kr":{"stem":"지문에 따르면, 극한생물이 주목할 만한 이유는?","opt":["다른 어떤 생물과도 다른 종류의 대사에 의존하기 때문에","그 외엔 치명적인 환경 속에서 평범한 생명 활동을 해내기 때문에","지구에서 가장 먼저 진화한 미생물이기 때문에","혹독한 서식지와 온화한 서식지를 빠르게 오가기 때문에"]}},"r_ac_02_2":{"a":2,"why":"둘째 문단은 효소의 단단한 접힘, 보호 화합물 축적처럼 **극한에서 살아남게 하는 구조적 특성들**을 설명해요. 그래서 '극한 환경 생존을 가능하게 하는 특성을 설명하는 것'이 목적이에요. 정의(B)나 의심 제기(D)가 아니에요.","wrong":[null,null,null,null],"kr":{"stem":"둘째 문단의 목적은 무엇인가요?","opt":["극한생물이 회복력 있게 행동한다고 주장하려고","무엇이 극한생물의 자격을 만드는지 규정하려고","극한 환경에서의 생존을 가능하게 하는 특성을 설명하려고","극한생물이 파멸적 환경에서 버틸 만큼 튼튼한지 의심하려고"]}},"r_ac_02_3":{"a":3,"why":"'물을 밖으로 끌어내 ___'라는 맥락이에요. 삼투압이 세포에서 물을 빼내면 세포가 '말라 버린다'는 뜻이라, desiccate는 '**말리다(dry out)**'와 가장 가까워요.","wrong":[null,null,null,null],"kr":{"stem":"지문에서 \"desiccate\"와 의미가 가장 가까운 것은?","opt":["중독시키다","식히다","커지게 하다","말리다"]}},"r_ac_02_4":{"a":"1.2","why":"질문의 핵심은 '**짠 물의 생물이 물 손실을 어떻게 막느냐**'예요. 세 번째 문장이 '세포 안에 용질을 쌓아 **삼투압을 상쇄한다**'고 그 방법을 정확히 짚으니 정답이에요. 효소 이야기(둘째 문장)는 열에 대한 적응이라 달라요.","wrong":[null,null,null,null],"kr":{"stem":"아주 짠 물에 사는 생물이 세포에서 물이 빠져나가는 것을 어떻게 막는지 설명하는 문장을 클릭하세요.","opt":["이러한 회복력을 가능하게 하는 적응은 행동만큼이나 구조적이다.","예컨대 열을 좋아하는 종의 효소는 여분의 화학 결합으로 강화된 유난히 단단한 형태로 접혀, 보통 단백질이라면 풀릴 온도에서도 제 기능의 형태를 유지한다.","고염 수역에 사는 생물은 세포 안에 적합성 용질을 쌓아, 물을 밖으로 끌어내 말려 버릴 삼투압을 상쇄한다.","각 경우에 분자의 안정성은 매우 특수한 변화를 통해 얻어져, 그 생물은 온화한 조건에서 살지 못하는 경우가 많다."]}},"r_ac_02_5":{"a":0,"why":"이 표현은 화성 염수와 나란히 '**태양계에서 생물이 살아남을 만한 장소**'의 예로 나와요. 즉 **지구 밖에서 생명이 이어질 수 있는 곳**을 가리키죠. 그래서 A가 정답이에요. 극한생물이 그리로 이동한다(B)거나 거기 생물이 확실히 있다(D)는 말은 아니에요.","wrong":[null,null,null,null],"kr":{"stem":"글쓴이는 왜 \"먼 위성의 얼음 덮인 바다\"를 언급하나요?","opt":["생물이 살 수 있는 지구 밖 장소를 가리키려고","극한생물이 다른 행성으로 이동할 수 있는 방법을 설명하려고","화성 생물의 구체적인 화학을 설명하려고","그런 곳에 극한생물 종이 있다고 단언하려고"]}}},"kr":{"passage":["극한생물은 한때 어떤 생명체에도 치명적이라 여겨지던 조건에서 번성하는 미생물로, 펄펄 끓는 열수 분출구나 광물로 포화된 소금 호수, 농축 산에 버금가게 부식성이 강한 산성 온천 속에서도 살아갑니다. 이들의 존재는 생물학자들이 생화학이 작동할 수 있는 물리적 한계를 다시 생각하게 만들었습니다. 이 생물들은 익숙한 생명체가 필요로 하는 것과 똑같은 기본적 대사와 번식 과정을 유지하지만, 보통의 단백질이라면 순식간에 파괴될 환경에서 그렇게 합니다.","이러한 회복력의 바탕이 되는 적응은 행동만큼이나 구조적입니다. 예컨대 열을 좋아하는 종의 효소는 여분의 화학 결합으로 강화된 유난히 단단한 형태로 접혀, 보통 단백질이라면 풀려 버릴 온도에서도 제 기능의 형태를 유지합니다. 아주 짠 물에 사는 생물은 세포 안에 보호 화합물을 쌓아, 물을 밖으로 끌어내 말려 버릴 삼투압을 상쇄합니다. 각 경우에 분자의 안정성은 매우 특수한 변화를 통해 얻어지기에, 그 생물은 오히려 온화한 조건에서는 살지 못하는 경우가 많습니다.","이 발견들의 중요성은 생물학적 진기함을 목록에 올리는 데 그치지 않습니다. 극한생물은 액체 물과 에너지원이 함께 있는 곳이라면 어디든 생명이 이어질 수 있음을 보여 주기에, 지하의 화성 염수부터 먼 위성의 얼음 덮인 바다에 이르기까지 태양계 다른 곳에서 생물이 살아남을 만한 장소에 대한 추정을 바꿔 놓았습니다. 그런 곳에 실제로 생명이 깃들어 있는지는 아직 밝혀지지 않았지만, 극한생물은 혹독함만으로 생명의 가능성을 배제할 수는 없음을 입증합니다."]}},"l_a01":{"q":{"l_a01_1":{"a":3,"why":"'어떻게' 제출하냐는 물음에 **학생 포털로 업로드하라**고 방법을 알려 준 D가 맞아요. B는 '언제'(시간), C는 예/아니오 대답이라 how와 안 맞아요.","wrong":[null,null,null,null],"kr":{"stem":"","opt":["걱정 마요. 아주 쉬워요.","다음 주 금요일 전 언젠가요.","네, 이미 보냈어요.","학생 포털로 업로드하세요."]}}},"script":[{"sp":"M","text":"How do I submit my aid form?"}],"kr":{"passage":["학자금 지원 서류는 어떻게 제출하나요?"]}},"l_a02":{"q":{"l_a02_1":{"a":0,"why":"많이 주냐는 물음에 **'제가 알기론 그렇다'**며 아는 선에서 답한 A가 자연스러워요. B는 pay를 '결제'로 받은 함정, D는 '어디' 답이라 안 맞아요.","wrong":[null,null,null,null],"kr":{"stem":"","opt":["제가 알기론 그래요.","계산대에서 결제해 주세요.","네, 저는 주말에 일해요.","주로 학생 식당에서요."]}}},"script":[{"sp":"W","text":"Do work-study jobs pay above minimum?"}],"kr":{"passage":["근로장학 일자리는 최저임금보다 많이 주나요?"]}},"l_a03":{"q":{"l_a03_1":{"a":1,"why":"분할 납부가 되냐는 물음에 **된다며 3회로 나뉜다**고 조건까지 답한 B가 정확해요. A는 pay off(성과를 내다)를 쓴 함정, D는 Please→Pleas 소리 함정이에요.","wrong":[null,null,null,null],"kr":{"stem":"","opt":["그 영화는 그렇게 화제였는데도 흥행에 실패했어요.","그럼요, 다만 3회로만 나눠 줘요.","맞아요. 바로 회계과 창구에서요.","정오까지 청원서에 서명해 주세요."]}}},"script":[{"sp":"M","text":"Can I pay tuition in installments?"}],"kr":{"passage":["등록금을 분할로 낼 수 있나요?"]}},"l_a04":{"q":{"l_a04_1":{"a":3,"why":"돈이 곧 들어온다는 소식에 **정말 필요했다**며 반긴 D가 맥락에 맞아요. A·B는 grant→granted·grand 소리 함정이에요.","wrong":[null,null,null,null],"kr":{"stem":"","opt":["허가가 빠르게 났어요.","그 그랜드 피아노 소리 참 좋네요.","요즘 등록금이 정말 비싸요.","잘됐네요, 정말 필요했거든요."]}}},"script":[{"sp":"W","text":"Your grant should arrive within two weeks."}],"kr":{"passage":["보조금이 2주 안에 들어올 거예요."]}},"l_a05":{"q":{"l_a05_1":{"a":2,"why":"온라인이 나은지 묻는 말에 **둘 다 되지만 온라인이 더 빠르다**고 조언한 C가 정확해요. B는 '언제'(시점) 답이라 should 질문과 안 맞아요.","wrong":[null,null,null,null],"kr":{"stem":"","opt":["그거 정말 신나겠네요.","첫 상환 바로 전에요.","둘 다 되지만 온라인이 더 빨라요.","대출은 정말 스트레스예요."]}}},"script":[{"sp":"M","text":"Should I do the loan counseling online?"}],"kr":{"passage":["대출 상담을 온라인으로 하는 게 좋을까요?"]}},"l_a06":{"q":{"l_a06_1":{"a":0,"why":"'언제' 나오냐는 물음에 **대략 이틀 정도**라고 기간을 답한 A가 맞아요. B는 come through를 '전화가 오다'로 받은 함정, D는 '누가' 답이라 when과 안 맞아요.","wrong":[null,null,null,null],"kr":{"stem":"","opt":["대략 이틀 정도요.","그 전화는 정오 직전에 왔어요.","네, 이미 신청했어요.","그건 지원과에서 처리해요."]}}},"script":[{"sp":"W","text":"When do emergency funds usually come through?"}],"kr":{"passage":["비상 지원금은 보통 언제 나오나요?"]}},"l_a07":{"q":{"l_a07_1":{"a":1,"why":"오전/오후 중 택하라는 물음에 **오후엔 일이 있다**며 오전을 에둘러 고른 B가 자연스러워요. A는 예/아니오라 택일 질문에 안 맞고, C는 advice(advising과 유사) 함정이에요.","wrong":[null,null,null,null],"kr":{"stem":"","opt":["네, 그러면 좋겠어요.","오후엔 할 일이 있어서요.","아까 조언 고마웠어요.","위층 상담실에서요."]}}},"script":[{"sp":"M","text":"Would you prefer morning or afternoon advising?"}],"kr":{"passage":["상담은 오전이 좋으세요, 오후가 좋으세요?"]}},"l_a08":{"q":{"l_a08_1":{"a":3,"why":"'누가' 승인하냐는 물음에 **학과 총괄자**라고 사람을 짚어 준 D가 맞아요. A는 '어디'(장소), B는 sign을 '간판'으로 받은 함정이에요.","wrong":[null,null,null,null],"kr":{"stem":"","opt":["아래층 학적과에서요.","어제 그 간판이 떨어졌어요.","네, 이미 다 됐어요.","당신 학과를 총괄하는 분이 누구든 그분이요."]}}},"script":[{"sp":"W","text":"Who signs off on my major form?"}],"kr":{"passage":["전공 신청서는 누가 승인해 주나요?"]}},"l_a09":{"q":{"l_a09_1":{"a":0,"why":"무엇을 보여 주냐는 물음에 **아직 이수 안 한 항목**을 알려 준다고 답한 A가 정확해요. B는 audit→audio 소리 함정, D는 '언제' 답이라 what과 안 맞아요.","wrong":[null,null,null,null],"kr":{"stem":"","opt":["아직 채워야 할 항목이 뭔지요.","오디오가 또 끊겼어요.","네, 제 건 괜찮아 보였어요.","등록 바로 전에요."]}}},"script":[{"sp":"M","text":"What does a degree audit actually show?"}],"kr":{"passage":["학위 이수 점검은 실제로 뭘 보여 주나요?"]}},"l_a10":{"q":{"l_a10_1":{"a":2,"why":"예외 등록을 부탁하는 말에 **제 권한이 아니다**라며 완곡히 거절한 C가 맞아요. A는 closed를 반복한 함정, B는 과거 감상이라 요청에 안 맞아요.","wrong":[null,null,null,null],"kr":{"stem":"","opt":["수업이 마감돼서 아쉽네요.","네, 그 수업 좋았어요.","그 결정은 제 소관이 아니에요.","아마 이번 주 중일 거예요."]}}},"script":[{"sp":"W","text":"Can you override the closed section for me?"}],"kr":{"passage":["마감된 분반을 저 대신 등록 허용해 주실 수 있나요?"]}},"l_a11":{"q":{"l_a11_1":{"a":1,"why":"마감이 언제냐는 물음에 **더 미루지 말라**며 임박했음을 넌지시 알린 B가 자연스러워요. A·D는 drop을 '갖다 놓다/이미 취소'로 받은 함정, C는 '어떻게' 답이라 when과 안 맞아요.","wrong":[null,null,null,null],"kr":{"stem":"","opt":["그거 사무실에 갖다 놓지 마세요.","저라면 더 미루진 않을 거예요.","학생 계정에서 온라인으로요.","저는 이미 취소했어요."]}}},"script":[{"sp":"M","text":"When is the last day to drop courses?"}],"kr":{"passage":["수강 취소 마지막 날이 언제예요?"]}},"l_a12":{"q":{"l_a12_1":{"a":3,"why":"대기자 합류 가능성을 묻자 **아직 일러 반반**이라고 전망을 답한 D가 맞아요. A는 wait-list를 '장보기 목록'으로 받은 함정, C는 순번 답이라 '가능성' 물음과 어긋나요.","wrong":[null,null,null,null],"kr":{"stem":"","opt":["장 볼 목록을 잃어버렸어요.","네, 저 붙었어요.","목록에서 네 번째예요.","솔직히 이렇게 이른 시점엔 반반이에요."]}}},"script":[{"sp":"W","text":"I was wondering about my wait-list odds."}],"kr":{"passage":["제 대기자 명단 가능성이 어떨지 궁금해서요."]}},"l_a13":{"q":{"l_a13_1":{"a":0,"why":"학점이 인정되냐는 물음에 **대부분 무리 없이 이월된다**고 답한 A가 맞아요. B는 credit을 '공로'로 받은 함정, C는 '어디' 답이라 예/아니오 질문과 안 맞아요.","wrong":[null,null,null,null],"kr":{"stem":"","opt":["대부분은 무리 없이 이월될 거예요.","그건 제 공으로 할게요.","보통은 학적 시스템에서요.","네, 그것들 어려웠어요."]}}},"script":[{"sp":"M","text":"Do my transfer credits count here?"}],"kr":{"passage":["제 편입 학점이 여기서 인정되나요?"]}},"l_a14":{"q":{"l_a14_1":{"a":2,"why":"어떤 서류냐는 물음에 **아직 세부가 정해지는 중**이라 확정 답을 못 준다는 C가 맥락상 자연스러워요. A는 '언제', B는 file을 '컴퓨터 파일'로 받은 함정이에요.","wrong":[null,null,null,null],"kr":{"stem":"","opt":["봄 학기 마감 전에요.","파일을 바탕화면에 저장하는 거 잊지 마세요.","세부 사항이 아직 정리되는 중이에요.","네, 곧 졸업해요."]}}},"script":[{"sp":"W","text":"Which form do I file to graduate?"}],"kr":{"passage":["졸업하려면 어떤 서류를 제출하나요?"]}},"l_a15":{"q":{"l_a15_1":{"a":1,"why":"'어떻게' 예약하냐는 물음에 **학생 포털에서 신청하라**고 방법을 알려 준 B가 맞아요. D는 '언제' 답이라 how와 안 맞고, A는 writing→riding 소리 함정이에요.","wrong":[null,null,null,null],"kr":{"stem":"","opt":["저는 자전거 타는 걸 정말 좋아해요.","학생 포털에서 신청하세요.","네, 정말 도움이 됐어요.","기말 주간 전 아무 때나요."]}}},"script":[{"sp":"M","text":"How do I get a writing appointment?"}],"kr":{"passage":["글쓰기 상담 예약은 어떻게 하나요?"]}},"l_b01":{"q":{"l_b01_1":{"a":0,"why":"여자가 **'정지되기 전에 누가 쓸 수 있냐'**고 물어 부정 사용을 걱정했어요(A). D의 '분실'은 맞지만 그가 물은 '걱정'의 핵심이 아니고, B(수수료 걱정)는 대화에 없어요.","wrong":[null,null,null,null],"kr":{"stem":"여자가 걱정하는 것은 무엇인가요?","opt":["정지 전에 누군가 카드를 쓸까 봐","특급 수수료가 너무 비쌀까 봐","카드를 영영 못 받을까 봐","체크카드를 어디 뒀는지 몰라서"]}},"l_b01_2":{"a":2,"why":"남자가 **'수수료로 특급 발송이 가능하다'**고 하자 여자가 '그렇게 하겠다'고 했으니 C가 맞아요. 7일이 오래 걸린다고 했으니 A(다 기다림)와 반대예요.","wrong":[null,null,null,null],"kr":{"stem":"여자는 이후 무엇을 할 가능성이 높나요?","opt":["7일을 다 기다린다","다른 지점을 방문한다","돈을 더 내고 배송을 앞당긴다","온라인으로 직접 카드를 정지한다"]}}},"script":[{"sp":"W","text":"Hi, I think I lost my debit card and need a new one."},{"sp":"M","text":"No problem. I can cancel the old one and order a replacement."},{"sp":"W","text":"Will someone be able to use it before it's canceled?"},{"sp":"M","text":"I'll deactivate it right now, so you'll have peace of mind."},{"sp":"W","text":"Oh, good. How soon will the new card arrive?"},{"sp":"M","text":"It should reach you within seven business days."},{"sp":"W","text":"Hmm..that's quite a while. Is there any way to get one faster?"},{"sp":"M","text":"We can rush it for a small fee if you'd like."},{"sp":"W","text":"Let's do that, better safe than sorry. Thanks."}],"kr":{"passage":["여: 안녕하세요, 제 체크카드를 잃어버린 것 같아서 새로 발급받아야 해요.","남: 문제없어요. 기존 카드를 정지하고 재발급을 신청해 드릴게요.","여: 정지되기 전에 누가 쓸 수도 있나요?","남: 지금 바로 정지해 드릴게요, 그러니 안심하셔도 돼요.","여: 아, 다행이네요. 새 카드는 얼마나 빨리 오나요?","남: 영업일 기준 7일 안에 도착할 거예요.","여: 음, 좀 오래 걸리네요. 더 빨리 받을 방법이 있을까요?","남: 원하시면 소액 수수료로 특급 발송해 드릴 수 있어요.","여: 그렇게 할게요, 만일을 대비하는 게 낫죠. 감사합니다."]}},"l_b02":{"q":{"l_b02_1":{"a":2,"why":"직원이 **'서류 하나가 아직 빠졌다'**고 했고, 그게 서명한 대출 동의서예요(C). A(학번 무효)·B(신청서 분실)는 언급이 없어요.","wrong":[null,null,null,null],"kr":{"stem":"남자의 학자금 지원금이 지급되지 않은 이유는?","opt":["학번이 유효하지 않아서","사무실이 그의 신청서를 통째로 분실해서","필요한 서류가 아직 빠져서","지원금이 다른 계정으로 가서"]}},"l_b02_2":{"a":1,"why":"여자가 **'한 부 출력해 주겠다'**고 했으니 B가 맞아요. 지급은 서명 후의 일이라 C는 성급하고, 서명은 남자가 직접 하니 A도 아니에요.","wrong":[null,null,null,null],"kr":{"stem":"여자는 다음에 무엇을 하나요?","opt":["서류를 대신 작성한다","그에게 사본을 출력해 준다","즉시 지원금을 지급한다","학번을 다시 묻는다"]}}},"script":[{"sp":"M","text":"Excuse me, my financial aid hasn't shown up in my account yet."},{"sp":"W","text":"Let me check. Can I have your student ID number?"},{"sp":"M","text":"Sure, let me pull it up on my phone."},{"sp":"W","text":"Thanks. It looks like one form is still missing."},{"sp":"M","text":"Really? Which one do I need to submit? I thought I'd gone through all the requirements."},{"sp":"W","text":"Your signed loan agreement. It's required before we release funds."},{"sp":"M","text":"I can't believe I overlooked that. I can sign it right now if you have a copy."},{"sp":"W","text":"Actually, I do. I'll print one out for you."},{"sp":"M","text":"Great. Thanks."}],"kr":{"passage":["남: 실례합니다, 제 학자금 지원금이 아직 계정에 안 들어왔어요.","여: 확인해 볼게요. 학번 좀 알려 주시겠어요?","남: 네, 휴대폰에서 찾아볼게요.","여: 감사해요. 보니까 서류 하나가 아직 빠졌네요.","남: 정말요? 어떤 걸 내야 하죠? 요건은 다 갖춘 줄 알았는데요.","여: 서명한 대출 동의서요. 지원금 지급 전에 꼭 필요해요.","남: 그걸 놓쳤다니 믿기지 않네요. 사본이 있으면 지금 바로 서명할게요.","여: 마침 있어요. 한 부 출력해 드릴게요.","남: 좋아요. 감사합니다."]}},"l_c01":{"q":{"l_c01_1":{"a":3,"why":"**'낡은 기계를 더 빠른 컬러 프린터로 교체했다'**고 했으니 컬러 인쇄가 빨라졌어요(D). 예약이 필요한 건 새 '포스터 프린터'뿐이라 C(모든 컬러)는 과장이에요.","wrong":[null,null,null,null],"kr":{"stem":"지금 인쇄실에 대해 추론할 수 있는 것은?","opt":["인쇄실이 훨씬 넓어졌다","이제 포스터만 인쇄할 수 있다","모든 컬러 프린터에 예약이 필요하다","컬러 인쇄가 전보다 빨라졌다"]}},"l_c01_2":{"a":1,"why":"**'온라인으로 시간대를 예약하라'**고 했으니 B가 맞아요. 요금 언급은 없고, 안내문은 웹이 아니라 '기기 옆'에 붙어 있어요.","wrong":[null,null,null,null],"kr":{"stem":"포스터 프린터를 쓰려면 학생들은 무엇을 해야 하나요?","opt":["온라인으로 요금을 낸다","시간대를 예약한다","웹사이트에서 안내문을 읽는다","다음 달까지 기다린다"]}}},"script":[{"sp":"W","text":"Just a heads up about some new equipment in the printing lab. We've replaced the two old machines with faster color printers, and we've added a large-format printer that can handle posters up to three feet wide. This is perfect for anyone getting ready for the research showcase next month. Because the poster printer is brand new, we're asking students to book a time slot online rather than just showing up. A short guide is posted next to each station."}],"kr":{"passage":["인쇄실 새 장비에 대해 잠깐 알려 드려요. 낡은 기계 두 대를 더 빠른 컬러 프린터로 교체했고, 최대 3피트 폭 포스터까지 뽑을 수 있는 대형 프린터도 새로 들였어요.","다음 달 연구 발표회를 준비하는 분들께 딱이에요.","포스터 프린터는 완전 새 거라, 그냥 오지 마시고 온라인으로 시간대를 예약해 주세요.","각 기기 옆에 간단한 안내문을 붙여 뒀어요."]}},"l_c02":{"q":{"l_c02_1":{"a":0,"why":"**'경험이 전혀 필요 없다'**고 했으니 초보자를 환영해요(A). 경기는 '저녁'에 열려서 C(오전)는 틀려요.","wrong":[null,null,null,null],"kr":{"stem":"이 교내 스포츠 프로그램에 대해 추론할 수 있는 것은?","opt":["초보자를 환영한다","우승자에게 상품을 준다","오전에 모인다","회비를 받는다"]}},"l_c02_2":{"a":2,"why":"**'처음으로 실내 암벽등반을 운영한다'**고 했으니 C가 맞아요. 배구·축구는 원래 있던 종목이에요.","wrong":[null,null,null,null],"kr":{"stem":"이번 시즌 처음 운영되는 종목은 무엇인가요?","opt":["수영 강습","야외 축구 경기","실내 암벽등반","배구 선수권"]}}},"script":[{"sp":"M","text":"Looking for a fun way to stay active this spring without joining a serious team? Registration for intramural sports is now open, and this season we're offering volleyball, soccer, and, for the first time, indoor rock climbing. You don't need any experience, and you can sign up alone or bring a group of friends. Games are played in the evenings, so they won't clash with your classes. Just fill out the form on the recreation center website before Friday."}],"kr":{"passage":["진지한 팀에 들지 않고도 이번 봄에 활동적으로 지낼 재미난 방법을 찾고 있나요? 교내 스포츠 등록이 시작됐고, 이번 시즌엔 배구, 축구, 그리고 처음으로 실내 암벽등반을 운영해요.","경험은 전혀 필요 없고, 혼자 신청해도 되고 친구들과 무리 지어 와도 돼요.","경기는 저녁에 열려서 수업과 겹치지 않아요.","금요일 전에 레크리에이션 센터 웹사이트에서 양식만 작성하세요."]}},"l_d01":{"q":{"l_d01_1":{"a":2,"why":"**'동아프리카의 건조한 토양 속 지하에서 수백 마리 군집으로 산다'**고 했으니 C가 맞아요. 물에 잠긴 지역(A)이 아니라 마른 토양이에요.","wrong":[null,null,null,null],"kr":{"stem":"화자에 따르면 벌거숭이두더지쥐는 어디에 사나요?","opt":["동아프리카의 물에 잠긴 지역에","숲 근처 마른 굴에","마른 토양 속 지하의 큰 군집에","암컷 한 마리가 있는 가족 무리에"]}},"l_d01_2":{"a":0,"why":"대부분은 **'여왕의 새끼를 위해 굴을 파고 먹이를 모으며 둥지를 지킨다'**고 했으니, 어린 개체(여왕의 새끼)를 위해 일하는 A가 맞아요. 여왕 경쟁(D)은 여왕이 죽었을 때뿐이에요.","wrong":[null,null,null,null],"kr":{"stem":"화자에 따르면 대부분의 성체 벌거숭이두더지쥐는 무엇을 하나요?","opt":["어린 개체들을 위해 일한다","돌아가며 새끼를 낳는다","먹이 접근을 늘리려 굴만 판다","다음 여왕이 되려 경쟁한다"]}},"l_d01_3":{"a":1,"why":"혈연관계 언급 뒤 **'여왕의 새끼를 돕는 개체도 자기 유전자를 간접적으로 전달한다'**고 이어져요. 번식 안 하는 개체의 유전자 전달을 설명하려는 것이라 B가 맞아요.","wrong":[null,null,null,null],"kr":{"stem":"화자는 왜 군집 구성원이 서로 가깝게 연결돼 있다고 언급하나요?","opt":["일부 새끼가 왜 비슷한 유전 형질을 공유하는지 설명하려고","번식하지 않는 개체가 왜 여전히 유전 형질을 전달하는지 설명하려고","군집이 왜 수백 마리로 커지는지 보여 주려고","새 여왕이 결국 어떻게 정해지는지 묘사하려고"]}},"l_d01_4":{"a":2,"why":"**'암에 놀랍도록 강하고 몸집에 비해 훨씬 오래 산다'**고 했으니 C가 맞아요. 이 점이 노화 연구에 가치 있다고 했어요.","wrong":[null,null,null,null],"kr":{"stem":"화자는 무엇이 벌거숭이두더지쥐를 과학적으로 가치 있게 만든다고 하나요?","opt":["몇 달간 먹이 없이 버티는 능력","곤충에 견줄 만한 유난히 큰 군집","특정 질병(암)에 대한 저항성과 장수","강력한 공동체를 이루는 사회적 기술"]}}},"script":[{"sp":"W","text":"Here's something that overturns what we expect from mammals. In a colony of naked mole-rats, only a single female ever gives birth. The dozens of other adults, though perfectly capable, never reproduce. Instead, they spend their whole lives digging tunnels, gathering food, and defending the nest for the offspring of that one queen. Biologists call this arrangement eusociality, and until it was found in these odd little rodents, it was thought to belong almost entirely to insects like ants, bees, and termites. Naked mole-rats live underground in the dry soils of East Africa, in colonies that can number in the hundreds. The queen dominates through constant, aggressive shoving that keeps the other females from breeding at all. When she dies, several females compete fiercely, sometimes fatally, and one eventually takes the throne, her body actually lengthening to bear young. Why would healthy adults surrender the chance to reproduce? Part of the answer lies in their tight relatedness. Because colony members are closely related, an individual that helps raise the queen's pups is still passing on many of its own genes indirectly. In a harsh environment where digging alone would be nearly impossible, cooperation pays. What makes these animals so valuable to science, though, reaches beyond their social lives. They resist cancer remarkably well and live far longer than a rodent their size should. Studying how a mammal built a society more like an insect's may teach us as much about aging as about cooperation itself."}],"kr":{"passage":["포유류에 대한 우리의 예상을 뒤엎는 사실이 있습니다. 벌거숭이두더지쥐 군집에서는 오직 한 마리의 암컷만 새끼를 낳습니다. 나머지 수십 마리 성체는 번식 능력이 충분한데도 결코 번식하지 않고, 평생 굴을 파고 먹이를 모으며 그 한 여왕의 새끼를 위해 둥지를 지킵니다. 생물학자들은 이 체계를 진사회성(eusociality)이라 부르며, 이 설치류에서 발견되기 전까지는 개미·벌·흰개미 같은 곤충에게나 거의 전적으로 해당하는 것으로 여겨졌습니다.","벌거숭이두더지쥐는 동아프리카의 건조한 토양 속 지하에서 수백 마리에 이르는 군집을 이루어 삽니다. 여왕은 끊임없는 공격적 밀치기로 다른 암컷들이 아예 번식하지 못하게 지배합니다. 여왕이 죽으면 여러 암컷이 때로 목숨을 걸고 치열히 경쟁하고, 결국 한 마리가 왕좌를 차지하며 새끼를 배기 위해 실제로 몸이 길어집니다.","건강한 성체들이 왜 번식 기회를 포기할까요? 답의 일부는 긴밀한 혈연관계에 있습니다. 군집 구성원이 서로 가깝게 연결돼 있어, 여왕의 새끼를 기르는 개체는 여전히 자기 유전자의 상당 부분을 간접적으로 전달하는 셈입니다. 혼자서는 굴 파기가 거의 불가능한 혹독한 환경에서 협력은 이득이 됩니다.","다만 이 동물이 과학에 갖는 가치는 사회생활을 넘어섭니다. 이들은 암에 놀랍도록 강하고 몸집에 비해 훨씬 오래 삽니다. 곤충에 가까운 사회를 이룬 포유류를 연구하는 일은 협력만큼이나 노화에 대해서도 많은 것을 가르쳐 줄 수 있습니다."]}},"l_a16":{"q":{"l_a16_1":{"a":2,"why":"'왜' 연결이 안 되냐는 원인을 묻는 말에 **드라이버 업데이트가 필요할 것**이라고 짚은 C가 맞아요. A는 connect를 '만나다'로, D는 printer→pointer 소리로 받은 함정이에요.","wrong":[null,null,null,null],"kr":{"stem":"","opt":["언제 커피나 한잔해요.","네, 지금 인쇄되고 있어요.","아마 드라이버 업데이트할 때가 됐을 거예요.","포인터가 작동을 멈췄어요."]}}},"script":[{"sp":"M","text":"Why won't the printer connect to Wi-Fi?"}],"kr":{"passage":["프린터가 왜 와이파이에 연결이 안 되죠?"]}},"l_a17":{"q":{"l_a17_1":{"a":0,"why":"연장이 되냐는 물음에 **2주 더 가능하다**고 기간까지 답한 A가 정확해요. B는 '안 된다'로 반대, D는 renewal→removal 소리 함정이에요.","wrong":[null,null,null,null],"kr":{"stem":"","opt":["네, 2주 더요.","이건 자격이 안 돼요.","네, 3층 서가에 있어요.","오늘 철거 팀이 왔어요."]}}},"script":[{"sp":"W","text":"Is this book eligible for renewal?"}],"kr":{"passage":["이 책 대출 연장이 되나요?"]}},"l_a18":{"q":{"l_a18_1":{"a":3,"why":"택배가 와 있다는 안내에 **이따 들르겠다**고 반응한 D가 자연스러워요. A는 package→pack, B는 mailroom→ballroom 소리 함정이에요.","wrong":[null,null,null,null],"kr":{"stem":"","opt":["오늘 밤에 짐 싸야 해요.","그 연회장 정말 근사해 보였어요.","그거 한참 전에 주문했는데.","이따 들를게요."]}}},"script":[{"sp":"M","text":"Your package is waiting in the mailroom."}],"kr":{"passage":["택배가 우편실에서 기다리고 있어요."]}},"l_a19":{"q":{"l_a19_1":{"a":1,"why":"허가증이 필요하냐는 물음에 **'이 학교 학생이냐'고 되물어** 답이 학생 여부에 달렸음을 시사한 B가 자연스러워요. A는 park를 '공원'으로, D는 permit→summit 소리로 받은 함정이에요.","wrong":[null,null,null,null],"kr":{"stem":"","opt":["우리 공원을 걸어서 지나갔어요.","이 학교 학생이세요?","평일 시간대에만요.","정상 회담은 다음 주예요."]}}},"script":[{"sp":"W","text":"Do I need a permit to park in the campus parking lot?"}],"kr":{"passage":["교내 주차장에 대려면 허가증이 필요한가요?"]}},"l_a20":{"q":{"l_a20_1":{"a":2,"why":"무엇이 필요하냐는 물음에 **소유 증빙을 가져오라**고 준비물을 답한 C가 맞아요. A는 '어디', B는 bike→hike 소리 함정이에요.","wrong":[null,null,null,null],"kr":{"stem":"","opt":["보안 사무실 쪽에서요.","우리 긴 하이킹을 갔어요.","소유 증빙을 가져오세요.","네, 제 건 등록돼 있어요."]}}},"script":[{"sp":"M","text":"What do I need to register my bike?"}],"kr":{"passage":["자전거 등록하려면 뭐가 필요한가요?"]}},"l_a21":{"q":{"l_a21_1":{"a":0,"why":"'언제' 찾냐는 물음에 **편할 때 아무 때나**라고 시점을 답한 A가 맞아요. B는 '어디', C는 card를 '생일 카드'로 받은 함정이에요.","wrong":[null,null,null,null],"kr":{"stem":"","opt":["편하실 때 아무 때나요.","카드 서비스 데스크에서요.","제가 생일 카드에 서명했어요.","네, 제 걸 잃어버렸어요."]}}},"script":[{"sp":"W","text":"When can I pick up a replacement ID?"}],"kr":{"passage":["재발급 학생증은 언제 찾아갈 수 있나요?"]}},"l_a22":{"q":{"l_a22_1":{"a":3,"why":"'어디에' 신고하냐는 물음에 **근무 중인 사감(RA)**이라고 대상을 짚어 준 D가 맞아요. B는 report를 '뉴스 기사'로 받은 함정, C는 예/아니오라 where과 안 맞아요.","wrong":[null,null,null,null],"kr":{"stem":"","opt":["저는 이해가 안 돼요.","그거에 관한 뉴스 기사를 읽었어요.","네, 해결됐어요.","근무 중인 사감(RA)에게요."]}}},"script":[{"sp":"M","text":"Where do students report roommate disputes?"}],"kr":{"passage":["룸메이트 분쟁은 어디에 신고하나요?"]}},"l_b03":{"q":{"l_b03_1":{"a":3,"why":"여자가 **'또 밀리기 전에 지금 시간을 정하자'**고 했으니 D가 맞아요. 대본은 '오늘 밤에 쓰겠다'고 해 아직 안 썼고(C 오답), 카메라·세미나실 문제는 언급이 없어요.","wrong":[null,null,null,null],"kr":{"stem":"여자는 왜 시간을 바로 정하려 하나요?","opt":["미디어 랩의 카메라가 부족해서","세미나실이 금방 예약돼서","이미 대본을 다 써서","촬영이 또 미뤄지지 않도록"]}},"l_b03_2":{"a":1,"why":"남자가 **'미디어 랩에서 카메라를 빌리겠다'**고 했으니 B가 맞아요. 대본 초안은 여자가 쓰기로 했어요(A 오답).","wrong":[null,null,null,null],"kr":{"stem":"남자는 촬영에 무엇을 가져오나요?","opt":["조별 대본 초안","촬영용으로 빌린 카메라","다른 조원들 점심","세미나실 가는 길 안내"]}}},"script":[{"sp":"W","text":"We still need to record our part for the group video project."},{"sp":"M","text":"I know. Everyone keeps pushing it back, and it's due Monday."},{"sp":"W","text":"Let's just lock in a time now, before it slips again."},{"sp":"M","text":"How about tomorrow afternoon? I can borrow a decent camera from the media lab."},{"sp":"W","text":"Perfect. Where should we shoot? Somewhere quiet, hopefully."},{"sp":"M","text":"The seminar room on the fourth floor is usually free."},{"sp":"W","text":"Good call. I'll write a rough script tonight so we're not winging it."},{"sp":"M","text":"And I'll message the other two to show up."},{"sp":"W","text":"Great, we've got this."}],"kr":{"passage":["여: 우리 조별 영상 과제, 우리 파트 아직 촬영해야 해요.","남: 그러게요. 다들 자꾸 미루는데 월요일 마감이잖아요.","여: 또 밀리기 전에 지금 시간을 딱 정해 버려요.","남: 내일 오후 어때요? 미디어 랩에서 괜찮은 카메라 하나 빌릴 수 있어요.","여: 좋아요. 어디서 찍죠? 조용한 데면 좋겠는데요.","남: 4층 세미나실이 보통 비어 있어요.","여: 좋은 생각이에요. 오늘 밤에 대본 초안을 써 올게요, 즉흥으로 하지 않게요.","남: 그럼 저는 나머지 둘한테 오라고 연락할게요.","여: 좋아요, 우리 할 수 있어요."]}},"l_b04":{"q":{"l_b04_1":{"a":0,"why":"남자가 **'동아리가 밴을 빌렸고 9시에 정문에서 출발한다'**고 했으니 A가 맞아요. 정문은 밴 출발지일 뿐이라 D(걸어서)는 오답이에요.","wrong":[null,null,null,null],"kr":{"stem":"자원봉사자들은 공원 청소에 어떻게 가나요?","opt":["동아리가 빌린 밴으로","일반 캠퍼스 셔틀로","다른 회원과 카풀로","정문에서 걸어서"]}},"l_b04_2":{"a":2,"why":"밴 얘기를 듣고 여자가 **'그게 제일 걱정이었다'**며 안도했으니, 교통편이 유일한 걸림돌이었어요(C). 그래서 A·D처럼 봉사 자체가 싫었던 건 아니에요.","wrong":[null,null,null,null],"kr":{"stem":"여자의 망설임에 대해 추론할 수 있는 것은?","opt":["야외 봉사를 싫어한다","그 토요일에 다른 일이 있었다","교통편이 유일한 진짜 걱정이었다","세 시간 있는 게 내키지 않았다"]}}},"script":[{"sp":"M","text":"Are you going to the park cleanup our club is organizing this Saturday?"},{"sp":"W","text":"I want to, but I'm not sure how I'd even get out there."},{"sp":"M","text":"The club rented a van. It's leaving from the main gate at nine in the morning."},{"sp":"W","text":"What a relief! That was my biggest concern. Anyway, do I need to bring anything?"},{"sp":"M","text":"Just gloves if you have them. They'll supply the bags and trash grabbers."},{"sp":"W","text":"Easy enough. How long are we out there for?"},{"sp":"M","text":"About three hours, and then they'll have pizza for everyone afterward."},{"sp":"W","text":"Sold. Count me in. I'll meet you at the gate."}],"kr":{"passage":["남: 이번 주 토요일에 우리 동아리가 여는 공원 청소 갈 거예요?","여: 가고 싶긴 한데, 거기까지 어떻게 갈지 모르겠어요.","남: 동아리가 밴을 빌렸어요. 아침 9시에 정문에서 출발해요.","여: 아 다행이다! 그게 제일 걱정이었거든요. 그런데 뭘 챙겨 가야 하나요?","남: 있으면 장갑만요. 봉투랑 집게는 제공돼요.","여: 간단하네요. 얼마나 있다 오나요?","남: 세 시간쯤이요, 끝나고는 다 같이 피자 먹어요.","여: 좋아요. 저 낄게요. 정문에서 봐요."]}},"l_c03":{"q":{"l_c03_1":{"a":1,"why":"**'재포장 공사로 폐쇄된다'**고 했으니 B가 맞아요. 공간 확충(A)이 아니라 노면 보수예요.","wrong":[null,null,null,null],"kr":{"stem":"C 주차장은 왜 폐쇄되나요?","opt":["주차 공간을 더 늘리려고","노면을 재포장하려고","F 주차장을 확장하려고","허가증 부족 때문에"]}},"l_c03_2":{"a":2,"why":"**'추가 비용 없이 F 주차장으로 옮겨 준다'**고 했으니 C가 맞아요. 스티커는 '찾아가는' 것이라 D(재신청)는 아니고, 걸어갈 시간을 더 잡으라 했으니 A(더 빨리)와 반대예요.","wrong":[null,null,null,null],"kr":{"stem":"C 주차장 배정 학생들에 대해 화자는 뭐라고 하나요?","opt":["강의실에 조금 더 빨리 도착한다","이제 교외에 주차해야 한다","무료로 다른 주차장으로 옮길 수 있다","새 허가증을 다시 신청해야 한다"]}}},"script":[{"sp":"W","text":"Good morning, everyone. We want to let you know that Lot C will close for repaving at the end of this month. If your permit is assigned to Lot C, you'll be moved to Lot F, near the science building, at no extra charge. New permit stickers are ready for pickup at our office this week. The work should take about six weeks, so build in a few extra minutes for your morning walk to class."}],"kr":{"passage":["안녕하세요 여러분. C 주차장이 이달 말에 재포장 공사로 폐쇄된다는 걸 알려 드려요.","C 주차장 배정 허가증을 갖고 계시면, 추가 비용 없이 과학관 근처 F 주차장으로 옮겨 드려요.","새 허가증 스티커는 이번 주에 저희 사무실에서 찾아가시면 돼요.","공사는 6주쯤 걸리니, 아침에 강의실까지 걸어갈 시간을 몇 분 더 잡아 두세요."]}},"l_c04":{"q":{"l_c04_1":{"a":2,"why":"네트워크를 **'더 빠르게 만드는'** 작업 때문이라 업그레이드가 이유예요(C). 다른 업체 교체(D)나 건물 수리(B)는 언급이 없어요.","wrong":[null,null,null,null],"kr":{"stem":"토요일에 무선 인터넷이 중단되는 이유는?","opt":["금요일까지 자료를 내려받아야 해서","회사 건물이 수리 중이라서","업그레이드 중이라서","다른 업체 것으로 교체돼서"]}},"l_c04_2":{"a":0,"why":"**'필요한 자료를 미리 내려받으라'**고 권했으니 A가 맞아요. 회의실 속도 향상은 작업 '완료 후' 얘기라 B와 무관해요.","wrong":[null,null,null,null],"kr":{"stem":"화자는 주말 전에 무엇을 하라고 권하나요?","opt":["필요한 자료를 미리 받아 둔다","회의실에서 무선 인터넷을 쓴다","더 빠른 속도를 IT팀에 신고한다","오후까지 컴퓨터 사용을 피한다"]}}},"script":[{"sp":"M","text":"Good morning, everyone. Our team has been working hard to make the campus network faster, and this weekend, it's finally happening. Because of that, the wireless internet will be down across most buildings on Saturday, from early morning until late afternoon. We suggest downloading anything you need for work ahead of time. Once we're finished, you should notice quicker speeds, especially in the meeting rooms. Thanks for your patience while we make things better."}],"kr":{"passage":["안녕하세요 여러분. 저희 팀이 캠퍼스 네트워크를 더 빠르게 만들려고 열심히 작업해 왔는데, 이번 주말에 드디어 진행돼요.","그래서 토요일 이른 아침부터 늦은 오후까지 대부분 건물에서 무선 인터넷이 중단돼요.","필요한 자료는 미리 내려받아 두시길 권해요.","작업이 끝나면 특히 회의실에서 속도가 더 빨라진 걸 느끼실 거예요. 개선하는 동안 양해해 주셔서 감사합니다."]}},"l_a23":{"q":{"l_a23_1":{"a":1,"why":"입주가 곧이라는 정보에 **그럼 서둘러야겠다**고 반응한 B가 맥락에 맞아요('get a move on'은 '서두르다'). A·C는 정보에 반응하지 않는 딴 얘기예요.","wrong":[null,null,null,null],"kr":{"stem":"","opt":["저는 주말엔 늘 바빠요.","그럼 저 서둘러야겠네요.","제 수업은 다음 주나 돼야 시작해요.","기숙사 정말 괜찮아 보였어요."]}}},"script":[{"sp":"W","text":"Freshmen move in on the weekend before classes."}],"kr":{"passage":["신입생 입주는 개강 전 주말이에요."]}},"l_a24":{"q":{"l_a24_1":{"a":2,"why":"마감이 지났냐(부정 의문문)는 확인에 **아직 시간 있다**고 정정해 준 C가 맞아요. A는 abroad→aboard, B는 pass를 '시험 통과'로 받은 소리 함정이에요.","wrong":[null,null,null,null],"kr":{"stem":"","opt":["캠퍼스 셔틀에 탑승하신 걸 환영해요.","네, 시험 통과하려고 정말 열심히 공부했어요.","아직 시간 있어요.","해외에서 공부해 보고 싶어요."]}}},"script":[{"sp":"M","text":"Didn't the study abroad deadline already pass?"}],"kr":{"passage":["해외 연수 마감 벌써 지나지 않았어요?"]}},"l_a25":{"q":{"l_a25_1":{"a":0,"why":"여기서 대여 기록(sign out)을 하냐는 물음에 **바인더에 기록하라**고 방법을 답한 A가 맞아요. B는 scope를 '규모'로, D는 microscope→telescope로 받은 함정이에요.","wrong":[null,null,null,null],"kr":{"stem":"","opt":["네, 바인더에 기록하세요.","그 규모가 어마어마해요.","아니요, 취소됐어요.","망원경은 대여 중이에요."]}}},"script":[{"sp":"W","text":"Do I sign out the microscope here?"}],"kr":{"passage":["현미경 대여 기록은 여기서 하나요?"]}},"l_b05":{"q":{"l_b05_1":{"a":1,"why":"남자가 **'혼자 공부하면 무너질 것'**이라고 했으니 B가 맞아요. 다른 시험(A)이나 메커니즘 약점(D)은 언급이 없어요.","wrong":[null,null,null,null],"kr":{"stem":"남자는 왜 중간고사를 걱정하나요?","opt":["그 주에 다른 시험이 여럿 있어서","혼자 공부하면 잘 못 볼 것 같아서","스터디 시간을 계속 못 맞춰서","반응 메커니즘이 제일 어려워서"]}},"l_b05_2":{"a":3,"why":"남자가 **'각자 한 챕터를 맡아 서로 가르치자'**고 제안했으니 D가 맞아요. 모임은 '토요일 오전'이라 A(평일 저녁)는 틀려요.","wrong":[null,null,null,null],"kr":{"stem":"남자는 준비를 위해 무엇을 제안하나요?","opt":["평일 저녁에 함께 모인다","조 단위로 화학 튜터를 고용한다","가장 어려운 메커니즘만 집중한다","각자 한 챕터씩 가르친다"]}}},"script":[{"sp":"W","text":"I'm putting together a study group for the organic chem midterm. You in?"},{"sp":"M","text":"Definitely. That exam's going to destroy me if I study alone."},{"sp":"W","text":"Same here. The trick is nailing down a time everyone's free."},{"sp":"M","text":"I'm swamped during the week, but my weekends are wide open."},{"sp":"W","text":"How about Saturday mornings? We could go over the reaction mechanisms then."},{"sp":"M","text":"Works for me. Should we each prep a chapter to teach the others?"},{"sp":"W","text":"Good idea. That way nobody just sits there passively."},{"sp":"M","text":"I'll take the first two chapters."},{"sp":"W","text":"Perfect. I'll email the rest of the group."}],"kr":{"passage":["여: 유기화학 중간고사 대비 스터디 그룹 만드는데, 같이 할래요?","남: 당연하죠. 혼자 공부하면 그 시험에 완전히 무너질 거예요.","여: 저도요. 관건은 다들 되는 시간을 딱 맞추는 거예요.","남: 저는 주중엔 정신없이 바쁜데 주말은 완전 비어요.","여: 토요일 오전 어때요? 그때 반응 메커니즘을 훑어보면 되겠어요.","남: 좋아요. 각자 한 챕터씩 맡아서 서로 가르쳐 줄까요?","여: 좋은 생각이에요. 그래야 아무도 그냥 멍하니 앉아 있지 않죠.","남: 제가 앞 두 챕터 맡을게요.","여: 완벽해요. 나머지 조원들한테 이메일 보낼게요."]}},"l_b06":{"q":{"l_b06_1":{"a":3,"why":"여자가 **'체육관에서 기부 물품을 분류할 사람이 부족하다'**고 했으니 D가 맞아요. 현금 모금(B)이 아니라 물품 분류예요.","wrong":[null,null,null,null],"kr":{"stem":"푸드 드라이브는 어떤 일에 자원봉사자가 필요한가요?","opt":["지역 주민에게 식사 배달","체육관에서 현금 기부 모금","봉사 서류 작성","기부받은 식품 분류"]}},"l_b06_2":{"a":1,"why":"여자가 **'학생 단체 사무실에서 양식을 작성하라'**고 했으니 직접 등록(B)이 맞아요. 온라인(A)이 아니라 현장 작성이에요.","wrong":[null,null,null,null],"kr":{"stem":"여자는 신청하려면 어떻게 하라고 하나요?","opt":["온라인 양식으로 신청한다","사무실에서 직접 등록한다","친구가 대신 등록하게 한다","오늘 바로 체육관으로 간다"]}}},"script":[{"sp":"W","text":"Have you signed up for the campus food drive this weekend yet?"},{"sp":"M","text":"Not yet. I didn't even know they still needed volunteers."},{"sp":"W","text":"They do! They're short on people to sort donations at the gym."},{"sp":"M","text":"Oh, I could do that. Is it a whole-day thing?"},{"sp":"W","text":"Nope, just three-hour shifts. I already picked the morning one."},{"sp":"M","text":"Then put me down for the same slot. The more the merrier."},{"sp":"W","text":"Perfect. You just fill out the form at the student org office."},{"sp":"M","text":"I'll swing by there after class."},{"sp":"W","text":"Great, they'll be thrilled to have you."}],"kr":{"passage":["여: 이번 주말 캠퍼스 푸드 드라이브 신청했어요?","남: 아직요. 아직도 자원봉사자가 필요한 줄 몰랐어요.","여: 필요해요! 체육관에서 기부 물품 분류할 사람이 부족하대요.","남: 아, 그거 제가 할 수 있어요. 온종일 하는 건가요?","여: 아니요, 3시간 교대예요. 저는 오전 걸로 골랐어요.","남: 그럼 저도 같은 시간대로 넣어 주세요. 사람 많을수록 좋죠.","여: 좋아요. 학생 단체 사무실에서 양식만 작성하면 돼요.","남: 수업 끝나고 들를게요.","여: 좋아요, 다들 반가워할 거예요."]}},"l_d02":{"q":{"l_d02_1":{"a":1,"why":"화자는 **'문자 없는 공동체가 긴 서사를 정확히 보존해 온 기법'**을 설명해요(B). 기록과의 단순 비교(A)가 요지가 아니에요.","wrong":[null,null,null,null],"kr":{"stem":"이 강의는 주로 무엇에 관한 것인가요?","opt":["기록과 구전의 비교","문자 없는 문화가 어떻게 이야기를 정확히 보존하는지","한 문화의 서사시 역사","연행자가 길고 어려운 대본을 어떻게 선보이는지"]}},"l_d02_2":{"a":2,"why":"**'리듬, 반복 어구, 예측 가능한 구조라는 틀에 의존한다'**고 했으니 C가 맞아요. '오직 리듬에만'(D)이 아니라 여러 요소를 함께 써요.","wrong":[null,null,null,null],"kr":{"stem":"화자에 따르면 연행자는 어떻게 긴 서사를 암송하나요?","opt":["대본처럼 모든 단어를 정확히 외워서","핵심 행을 미리 정확히 적어 두어서","익숙한 패턴과 반복 어구를 이용해서","오직 리듬 구조에만 의존해서"]}},"l_d02_3":{"a":0,"why":"**'박자에 맞는 어구가 산문보다 기억하기 쉽다'**며 음악성이 회상을 돕는 발판임을 설명해요(A).","wrong":[null,null,null,null],"kr":{"stem":"화자는 왜 리듬과 선율을 언급하나요?","opt":["음악성이 왜 회상을 돕는지 설명하려고","노래가 최고의 기억술이라고 주장하려고","선율이 모든 청중을 더 집중시킴을 보이려고","지역별 창법을 비교하려고"]}},"l_d02_4":{"a":1,"why":"**'문구는 달라져도 핵심 내용은 놀랍도록 안정적으로 유지된다'**고 했으니 B가 맞아요.","wrong":[null,null,null,null],"kr":{"stem":"화자는 구전의 정확성에 대해 무엇을 시사하나요?","opt":["정확한 문구가 보존된다","핵심 내용이 안정적으로 유지된다","이야기는 필연적으로 왜곡된다","짧은 것만 안정적으로 전달된다"]}}},"script":[{"sp":"M","text":"Have you ever wondered how a society without writing could preserve an epic poem thousands of lines long, reciting it accurately across generations? To a culture raised on books, it seems almost impossible. Surely, the story would drift and crumble with each retelling. Yet nonliterate communities have done exactly this for millennia, and the techniques they use reveal a great deal about human memory. The key is that these narratives are not memorized word for word like a script. Instead, performers rely on a flexible framework of rhythm, repeated phrases, and predictable structure. Set formulas, ready-made expressions that fit the meter, let a singer assemble lines on the spot while staying faithful to the tale. Rhythm and melody act as scaffolding, since a phrase that fits the beat is far easier to recall than loose prose. Vivid imagery and familiar patterns of events give the mind reliable anchors to hang the sequence on. What looks like flawless recall is really skilled reconstruction, guided by rules the performer absorbed since childhood. And this changes how we should think about accuracy itself. The wording may shift from one performance to the next, yet the essential content, the characters, the order of events, the moral weight, stays remarkably stable. In some traditions, communities even correct a performer who strays too far. So oral transmission is not a fragile game of telephone slowly distorting the message. It is a disciplined craft, and it reminds us that memory, properly trained, can be astonishingly robust."}],"kr":{"passage":["글이 없는 사회가 수천 행에 이르는 서사시를 어떻게 여러 세대에 걸쳐 정확히 암송해 보존했을까 궁금해한 적 있나요? 책에 익숙한 문화에는 거의 불가능해 보입니다. 다시 들려줄 때마다 이야기가 표류하고 무너질 것 같으니까요. 그러나 문자 없는 공동체는 수천 년간 바로 이 일을 해냈고, 그들이 쓰는 기법은 인간의 기억에 대해 많은 것을 알려 줍니다.","핵심은 이 서사가 대본처럼 한 단어 한 단어 외워지는 게 아니라는 점입니다. 대신 연행자는 리듬, 반복되는 어구, 예측 가능한 구조라는 유연한 틀에 의존합니다. 운율에 맞는 상투적 표현은 가수가 이야기에 충실하면서도 즉석에서 행을 엮어 내게 해 줍니다. 리듬과 선율은 발판 역할을 합니다. 박자에 맞는 어구가 흐트러진 산문보다 훨씬 기억하기 쉽기 때문입니다. 생생한 심상과 익숙한 사건 전개는 순서를 걸어 둘 든든한 닻이 됩니다.","완벽한 암기처럼 보이는 것은 사실 어릴 때부터 몸에 익힌 규칙에 따른 능숙한 재구성입니다. 이것은 '정확성'을 어떻게 봐야 할지를 바꿉니다. 문구는 공연마다 달라질 수 있지만, 등장인물·사건 순서·도덕적 무게 같은 핵심 내용은 놀랍도록 안정적으로 유지됩니다. 어떤 전통에서는 너무 벗어난 연행자를 공동체가 바로잡기도 합니다.","그러므로 구전은 메시지를 서서히 왜곡하는 취약한 '말 전하기 놀이'가 아닙니다. 그것은 훈련된 기술이며, 제대로 단련된 기억이 얼마나 놀랍도록 견고할 수 있는지를 일깨워 줍니다."]}},"l_d03":{"q":{"l_d03_1":{"a":3,"why":"**'둘 다 침묵하면 가벼운 혐의로만 기소돼 각각 1년을 산다'**고 했으니 D가 맞아요. 5년(C)은 둘 다 배신할 때의 결과예요.","wrong":[null,null,null,null],"kr":{"stem":"화자에 따르면 두 죄수가 모두 침묵하면 어떻게 되나요?","opt":["둘 다 아무 혐의 없이 풀려난다","둘 다 최대 10년형을 받는다","각각 5년을 산다","각각 1년만 감옥에 있는다"]}},"l_d03_2":{"a":0,"why":"**'상대가 무엇을 하든 배신은 개인적으로 늘 더 가벼운 형량을 가져온다'**고 했으니 A가 맞아요. 침묵은 상대도 침묵할 때만 유리해 B는 틀려요.","wrong":[null,null,null,null],"kr":{"stem":"화자에 따르면 합리적 참가자는 왜 배신을 택하나요?","opt":["배신이 자기 형량을 줄이기 때문에","침묵하면 자유가 보장되기 때문에","동료가 이미 모두 자백했기 때문에","동료가 상대가 배신했다고 가정하기 때문에"]}},"l_d03_3":{"a":0,"why":"회사·국가 예시는 **'이 함정이 감옥 밖 여러 분야에도 적용된다'**는 걸 보이려는 것이라 A가 맞아요. 담합(C)이나 소비자 피해(B)가 요지가 아니에요.","wrong":[null,null,null,null],"kr":{"stem":"화자는 왜 가격 전쟁 중인 두 회사를 언급하나요?","opt":["이 딜레마가 형사 사건 외의 분야에도 적용됨을 보이려고","가격 전쟁이 늘 두 회사에 해롭다고 주장하려고","회사들이 몰래 가격을 담합함을 설명하려고","회사가 오염 억제보다 저가를 우선함을 증명하려고"]}},"l_d03_4":{"a":1,"why":"**'게임이 반복되면 신뢰에 보상하고 배신을 응징하며 협력이 생겨난다'**고 했으니 B가 맞아요.","wrong":[null,null,null,null],"kr":{"stem":"화자는 무엇이 협력을 생겨나게 한다고 시사하나요?","opt":["모든 형벌의 강도를 높이는 것","같은 게임을 여러 번 반복하는 것","두 참가자가 제약 없이 소통하게 하는 것","참가자에게서 합리적 이기심을 없애는 것"]}}},"script":[{"sp":"W","text":"Picture two suspects arrested for a crime and held in separate rooms, unable to talk. Each is offered the same deal. Betray your partner and, if he stays silent, you walk free while he serves ten years. If you both betray each other, you each get five years. If you both stay silent, the police can only convict you of a minor charge, and you each serve one. This is the prisoner's dilemma, one of the most studied scenarios in game theory, and its lesson is unsettling. Think it through from one prisoner's point of view. Whatever the other does, betrayal always yields a lighter sentence for you personally. So a purely rational, self-interested player will betray, and since both reason identically, both betray, and both end up with five years. Yet had they cooperated and stayed silent, each would have served just one. Individually sensible choices produce a collectively worse result. What makes this so significant is how widely the pattern applies beyond any jail cell. Two companies locked in a price war, or nations reluctant to limit pollution, face the same trap: cooperation would benefit everyone, but the fear of being exploited pushes each side toward the mutually damaging option. Researchers have found that when the game is played repeatedly, cooperation can emerge, because players learn to reward trust and punish betrayal over time. That single insight, that repetition changes everything, has reshaped how economists and biologists alike explain why cooperation exists at all."}],"kr":{"passage":["범죄로 체포된 두 용의자가 서로 대화하지 못한 채 각각 다른 방에 갇혀 있다고 상상해 봅시다. 둘은 같은 제안을 받습니다. 동료를 배신했는데 그가 침묵하면 당신은 풀려나고 그는 10년을 삽니다. 둘 다 서로를 배신하면 각각 5년을 받습니다. 둘 다 침묵하면 경찰은 가벼운 혐의로만 기소할 수 있어 각각 1년을 삽니다.","이것이 게임 이론에서 가장 많이 연구된 시나리오 중 하나인 '죄수의 딜레마'이며, 그 교훈은 불편합니다. 한 죄수의 입장에서 따져 봅시다. 상대가 무엇을 하든 배신은 개인적으로 늘 더 가벼운 형량을 가져다줍니다. 그래서 순전히 합리적이고 이기적인 참가자는 배신을 택하고, 둘 다 똑같이 추론하므로 둘 다 배신해 결국 둘 다 5년을 받습니다. 하지만 협력해 침묵했다면 각각 1년만 살았을 것입니다. 개인적으로 합리적인 선택이 집단적으로는 더 나쁜 결과를 낳는 것입니다.","이것이 중요한 이유는 이 양상이 감옥 밖에서도 널리 적용되기 때문입니다. 가격 전쟁에 갇힌 두 회사나 오염을 줄이길 꺼리는 국가들도 같은 함정에 빠집니다. 협력하면 모두에게 이득이지만, 이용당할지 모른다는 두려움이 각 측을 서로에게 해로운 선택으로 몰아갑니다.","연구자들은 이 게임이 반복해서 진행되면 협력이 생겨날 수 있음을 발견했습니다. 시간이 지나며 참가자들이 신뢰에 보상하고 배신을 응징하는 법을 배우기 때문입니다. '반복이 모든 것을 바꾼다'는 이 통찰 하나가, 협력이 애초에 왜 존재하는지를 경제학자와 생물학자 모두가 설명하는 방식을 바꿔 놓았습니다."]}},"w_bas_01":{"items":[{"id":"w_bas_01_1","solution":["I","chose","the one","my","mom","liked"],"answer":"I chose the one my mom liked."},{"id":"w_bas_01_2","solution":["where","did","the manager","put","the","extra","keys"],"answer":"Where did the manager put the extra keys?"},{"id":"w_bas_01_3","solution":["nobody","knows","why","the","new policy","was","cancelled"],"answer":"Nobody knows why the new policy was cancelled."},{"id":"w_bas_01_4","solution":["gave","a","short","quiz","to","the class"],"answer":"The teacher gave a short quiz to the class."},{"id":"w_bas_01_5","solution":["have","to finish","the","monthly","report","before","lunch"],"answer":"They have to finish the monthly report before lunch."},{"id":"w_bas_01_6","solution":["is","the","most","expensive","of","all","the current ones"],"answer":"This laptop is the most expensive of all the current ones."},{"id":"w_bas_01_7","solution":["so","does","everyone","else","here"],"answer":"So does everyone else here."},{"id":"w_bas_01_8","solution":["our","team","has","made","a lot","of","progress"],"answer":"Our team has made a lot of progress."},{"id":"w_bas_01_9","solution":["was","sent","to","every","member","of","the staff"],"answer":"The email was sent to every member of the staff."},{"id":"w_bas_01_10","solution":["should","pay","close","attention","to","the details"],"answer":"You should pay close attention to the details."}],"kr":{"items":[{"prompt_ko":"어느 아파트로 결국 정했어요?","answer_ko":"엄마가 마음에 들어 한 곳으로 골랐어요.","note":"**관계절**로 명사를 꾸며요. **the one** 뒤에 **(that) my mom liked**가 붙어 '엄마가 좋아한 그것'을 나타내요. 목적격 관계대명사 that은 생략돼 «the one + 주어 + 동사» 형태가 돼요."},{"prompt_ko":"지금 창고에 못 들어가겠어요.","answer_ko":"매니저가 여분 열쇠를 어디에 뒀나요?","note":"**직접 의문문(Wh-)** 이에요. **Where + did + 주어 + 동사원형(put)** 순서로, 과거라 did를 쓰고 동사는 원형으로 돌아가요."},{"prompt_ko":"규칙 변경에 대해 설명해 준 적 있어요?","answer_ko":"새 규정이 왜 취소됐는지 아무도 몰라요.","note":"**간접의문문**이에요. knows 뒤에 **why + 주어 + 동사**가 평서문 어순으로 들어가요(why the new policy was cancelled). 여기에 **수동태(was cancelled)**가 겹쳐 있어요."},{"prompt_ko":"오늘 아침에 왜 다들 이렇게 긴장한 표정이에요?","answer_ko":"선생님이 반에 짧은 쪽지시험을 냈어요.","note":"**수여동사 give**의 3형식 변형이에요. **give + 사물(a short quiz) + to + 사람(the class)** 순서로, 사람을 뒤로 뺄 땐 **to**를 붙여요."},{"prompt_ko":"팀은 마감을 어떻게 맞출 계획인가요?","answer_ko":"그들은 점심 전에 월간 보고서를 끝내야 해요.","note":"**have to + 동사원형** 구조예요. '~해야 한다'는 의무를 나타내고 **have to finish**로 이어져요. **before lunch**(점심 전에)로 시점을 붙여요."},{"prompt_ko":"최근에 컴퓨터를 바꿨다고 들었어요.","answer_ko":"이 노트북이 현재 나온 것 중 가장 비싸요.","note":"**최상급(the most + 형용사)** 구조예요. 3음절 이상 형용사는 **the most expensive**로 만들고 범위는 **of all ...**로 나타내요."},{"prompt_ko":"새 일정이 훨씬 낫다고 생각해요.","answer_ko":"여기 다들 그렇게 생각해요.","note":"**So + 동사 + 주어** 도치 구조예요. '~도 그렇다'는 동의를 나타내고, 앞 문장이 일반동사(think) 현재형이라 대동사 **does**를 써서 **So does everyone else**가 돼요."},{"prompt_ko":"요즘 프로젝트는 어떻게 돼 가요?","answer_ko":"우리 팀은 많은 진전을 이뤘어요.","note":"**현재완료(has + p.p.)** 구조예요. **has made**로 '(지금까지) 해냈다'는 결과를 나타내요. **make progress**(진전을 이루다)는 자주 쓰는 표현이에요."},{"prompt_ko":"일정 변경 소식 다들 들었어요?","answer_ko":"그 이메일은 전 직원에게 발송됐어요.","note":"**수동태(be + p.p.)** 구조예요. **The email was sent**로 '이메일이 보내졌다'를 나타내고 받는 대상은 **to** 뒤에 놓아요(to every member of the staff)."},{"prompt_ko":"이 양식에서 자꾸 같은 실수를 해요.","answer_ko":"세부 사항에 세심히 주의를 기울여야 해요.","note":"**조동사 should** 구조예요. **should + 동사원형(pay)**로 조언을 나타내요. **pay attention to**(~에 주의를 기울이다)는 굳어진 표현이라 to를 빠뜨리지 않아요."}]}},"w_em_01":{"model":"","rubric":[],"kr":{"situation_ko":"교수님(오카포 박사님)이 추천서를 써 주신 덕분에 교환학생 프로그램에 합격했어요. 방금 합격 통보를 받았고, 교수님의 지도가 앞으로의 목표에 어떤 영향을 줬는지도 짧게 전하고 싶어요.","directions_ko":["추천서에 대해 감사 인사를 해요.","합격 소식과 그 프로그램이 당신에게 갖는 의미를 전해요.","교수님의 지도가 앞으로의 계획에 어떤 영향을 줬는지 설명해요."]}},"w_ad_01":{"model":"","rubric":[],"kr":{"prof_ko":"우리는 사람들이 제2언어를 어떻게 가장 잘 익히는지 살펴봤어요. 어떤 연구자들은 그 언어를 쓰는 나라에서 사는 '완전 몰입'이 자연스러운 유창성을 만든다고 주장해요. 다른 이들은 교실 수업이 더 튼튼한 장기적 토대를 쌓는다고 봐요. 새 언어를 배우는 데 어느 쪽이 더 낫다고 보나요, 그 이유는요?","posts_ko":[{"name":"Olivia","text_ko":"저는 몰입이 쉽게 이긴다고 봐요. 하루 종일 언어에 둘러싸이면 교재가 못 담는 슬랭, 리듬, 몸짓까지 사람들이 실제로 어떻게 말하는지 배워요. 저는 해외에서 석 달 만에, 몇 년간 수업으로 배운 것보다 더 많은 스페인어를 익혔어요. 계속 써야만 했으니까요."},{"name":"Ethan","text_ko":"몰입만으로는 같은 실수를 몇 년째 반복하는 자신감 넘치는 화자를 만드는 경우가 많아요. 오류를 고쳐 주고 문법을 설명해 줄 교사가 없으면 나쁜 습관이 굳어져요. 교실은 구조와 명확한 진행, 그리고 몰입이 좀처럼 주지 못하는 피드백을 줘요."}]}},"s_lr_01":{"items":[{"n":1,"text":"Our front reception counter is open every weekday morning. "},{"n":2,"text":"The sign-in tablet records your arrival time."},{"n":3,"text":"Sanitizing your hands, which only takes a few seconds, keeps the whole clinic safer. "},{"n":4,"text":"The bulletin board lists free wellness workshops this month."},{"n":5,"text":"Please take a paper cup from the water dispenser."},{"n":6,"text":"Patients whose names appear on the screen should step onto the weighing scale."},{"n":7,"text":"When you finish your visit, grab a helpful pamphlet from the wooden rack by the door."}]},"s_iv_01":{"items":[{"n":1,"text":"Let's start with your own experience. How often do you play video games, and on what kind of device—a phone, a console, or a computer? Think about the last game you really enjoyed and tell me what it was."},{"n":2,"text":"Thanks. When you play, do you prefer playing alone, or playing together with other people online or in the same room? Why?"},{"n":3,"text":"Interesting. Where you live, do you think playing video games is widely accepted as a normal hobby for adults, or is it still viewed as something mainly for children? Why do you think so?"},{"n":4,"text":"Good points. Some people believe that video games can build valuable skills like teamwork and problem-solving, and should even be used in schools as teaching tools. Do you agree or disagree? Why?"}]}}};
